//! 🧪️ Mixed SELECTs preserve the original constructor or ordinary reference carrier under strict candidate authority.
use super::*;
fn contract()->serde_json::Value{serde_json::from_str(include_str!("🧪️tests/type-mixed-select-input.json")).unwrap()}
fn value(row:&serde_json::Value)->IfcValue{match row["kind"].as_str().unwrap(){"unset"=>IfcValue::Unset,"reference"=>IfcValue::Reference(row["value"].as_str().unwrap().parse().unwrap()),"real"=>IfcValue::Real(f64::from_bits(row["value"]["bits"].as_str().unwrap().parse().unwrap())),"aggregate"=>IfcValue::Aggregate(row["value"].as_array().unwrap().iter().map(value).collect()),"typedValue"=>IfcValue::TypedValue(IfcTypedValue{name:row["value"]["name"].as_str().unwrap().into(),items:row["value"]["items"].as_array().unwrap().iter().map(value).collect()}),_=>panic!("closed source fixture")}}
fn source(law:&serde_json::Value)->Arc<IfcSnapshot>{Arc::new(IfcSnapshot{entities:law["source"]["entities"].as_array().unwrap().iter().map(|row|IfcEntity{id:row["id"].as_str().unwrap().parse().unwrap(),name:row["name"].as_str().unwrap().into(),args:row["args"].as_array().unwrap().iter().map(value).collect(),complex:row["complex"].as_array().unwrap().iter().map(|part|IfcComplexType{name:part["name"].as_str().unwrap().into(),args:part["args"].as_array().unwrap().iter().map(value).collect()}).collect()}).collect(),..Default::default()})}
fn event(law:&serde_json::Value,row:&serde_json::Value)->editing::SnapshotEditEvent{editing::SnapshotEditEvent::SetValue{path:"/entities/0".into(),value:super::type_input_tests::raw(&serde_json::json!({"$ifcType":law["entity"],"$ifcInputs":if row["input"].is_null(){serde_json::json!([])}else{serde_json::json!([{"index":law["index"],"value":row["input"]}])}}))}}
#[test]
fn original_mixed_select_cursor_visits_the_complete_domain_before_exposing_its_single_entity_branch(){
 if DetailsTestProfile::catalog().schema!="IFC4X3_ADD2"{return;}
 let attribute=DetailsTestProfile::normalization_attribute("IFCFILLAREASTYLEHATCHING",1,true).unwrap().unwrap();let mut cursor=super::super::super::type_input_kind::Cursor::default();let mut complete=None;for turn in 0..1024{let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance::<DetailsTestProfile>(attribute.type_expr));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));if let Some(kind)=answer.unwrap(){complete=Some(kind);assert!(turn>=2);break;}}assert_eq!(complete,Some(super::super::super::type_input_kind::Kind::Select));assert_eq!(cursor.reference_member(),Some(1));
}
#[test]
fn original_mixed_selects_use_central_actual_carriers_and_exact_inverse(){
 if DetailsTestProfile::catalog().schema!="IFC4X3_ADD2"{return;}
 let law=contract();for row in law["cases"].as_array().unwrap(){let snapshot=source(&law);let mut caller=OriginalWorkFixture::new();let mut work=Work::new(editing::SET_SNAPSHOT_VALUE_ACTION_ID);inputs(&snapshot,event(&law,row),&mut caller,&mut work,|input,caller,work|{let mut result=None;for turn in 0..1000000{match caller.work_turn(grant(),1,|cx|work.step(input,cx)){Ok(ArtifactCommandWorkStep::Complete(emit))=>{result=Some(Ok(emit));break;},Err(error)=>{result=Some(Err(error));break;},_=>{}}assert!(turn<999999);}let result=result.unwrap();assert_eq!(result.is_ok(),row["ready"].as_bool().unwrap(),"{}",row["id"]);if let Ok(emit)=result{assert_eq!(emit.artifact_mutations.len(),1);assert!(matches!(emit.artifact_mutations[0],IfcMutation::SetEntityArg(_)));let mutation=&emit.artifact_mutations[0];let inverse=mutation.inverse(&snapshot).unwrap();let mut next=protocol::apply_diff_cold(mutation.diff(&snapshot).diff(),&snapshot).unwrap();assert!(ifc_arguments_identical(&next.entities[0].args[1..2],&[value(&row["input"])]));assert!(ifc_complex_identical(&next.entities[0].complex,&snapshot.entities[0].complex));for mutation in inverse{next=protocol::apply_diff_cold(mutation.diff(&next).diff(),&next).unwrap();}assert!(ifc_arguments_identical(&next.entities[0].args,&snapshot.entities[0].args));assert!(ifc_complex_identical(&next.entities[0].complex,&snapshot.entities[0].complex));}super::constituent_optional_shape_tests::close_with_denials(caller,work);assert!(work.terminal_is_empty());});caller.finish();}
}
#[test]
fn original_mixed_select_donated_controls_keep_both_carriers_and_denied_axes_stationary(){
 use semio_framework_plugin::action_staging::*;use semio_framework_plugin_decl_staged_form::*;
 type Guidance=super::super::super::type_guidance::IfcTypeInputSourceWork<DetailsTestProfile>;
 if DetailsTestProfile::catalog().schema!="IFC4X3_ADD2"{return;}
 let law=contract();let mut cases=law["cases"].as_array().unwrap().clone();cases.push(serde_json::json!({"id":"utf8-reference-draft","input":{"kind":"reference","value":format!("{}ä{}","9".repeat(63),"🙂".repeat(20))},"ready":false,"physical":false}));for row in &cases{let snapshot=source(&law);let editing::SnapshotEditEvent::SetValue{path,value}=event(&law,row)else{unreachable!()};let mut donor=Some(StagedFormRequest{token:StagedFormToken{action:editing::SET_SNAPSHOT_VALUE_ACTION_ID.into(),window:"original-mixed-select".into(),generation:"1".into(),revision:"0".repeat(64)},locale:semio_framework_ui_locale::Locale::De,args:DslValue::Object(vec![("path".into(),DslValue::String(path)),("value".into(),value)]),page:None});let mut caller=OriginalWorkFixture::new();let mut guide=Some(Guidance::default());let mut output=None;assert!(caller.work_turn(grant(),1,|cx|guide.as_mut().unwrap().receive(&mut donor,&snapshot,[0;32],cx)).unwrap());for turn in 0..1000000{let demand=guide.as_ref().unwrap().demands().unwrap();let(repeated,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||guide.as_ref().unwrap().demands());assert_eq!(repeated.unwrap(),demand);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));for axis in 0..6{let mut denied=grant();let mut fuel=1;match axis{0=>denied.maximum_items=0,1 if demand.copy_bytes>0=>denied.maximum_copy_bytes=demand.copy_bytes-1,2 if demand.capacity_bytes>0=>denied.maximum_capacity_bytes=demand.capacity_bytes-1,3 if demand.release_bytes>0=>denied.maximum_release_bytes=demand.release_bytes-1,4 if demand.depth>0=>denied.maximum_depth=demand.depth-1,5=>fuel=0,_=>continue};let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.work_turn(denied,fuel,|cx|{let before=cx.retained_progress();let answer=guide.as_mut().unwrap().advance(&snapshot,[0;32],cx);assert_eq!(before,cx.retained_progress());answer}));assert!(!answer.unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}if caller.work_turn(grant(),1,|cx|guide.as_mut().unwrap().advance(&snapshot,[0;32],cx)).unwrap(){break;}assert!(turn<999999);}assert!(caller.work_turn(grant(),1,|cx|guide.as_mut().unwrap().take(&mut output,cx)).unwrap());let prepared=output.as_ref().unwrap();assert_eq!(prepared.status().ready,row["ready"].as_bool().unwrap());assert_eq!(prepared.controls(),if row["input"].is_null(){1}else{2});let control=prepared.control(0).unwrap();let StagedScalarKind::Choice{value,choices}=control.scalar.kind else{panic!("complete released mixed choices")};assert_eq!(choices.iter().map(|choice|choice.key).collect::<Vec<_>>(),["IFCPOSITIVELENGTHMEASURE","IFCVECTOR"]);assert_eq!(value,if row["input"].is_null(){""}else if row["input"]["kind"]=="reference"{"IFCVECTOR"}else{"IFCPOSITIVELENGTHMEASURE"});let StagedBodyBinding::Action(binding)=control.binding.unwrap()else{panic!("original choice")};for member in ["IFCPOSITIVELENGTHMEASURE","IFCVECTOR"]{let input=DslValue::String(member.into());let last=binding.plan(prepared.status(),Some(&input)).unwrap().last().unwrap();let semio_framework_plugin::action_staging::StagedFormBorrowedEdit::Set{value,..}=last else{panic!("closed branch replacement")};if member=="IFCVECTOR"{assert_eq!(value.get("kind").and_then(DslValue::as_str),Some("reference"));assert_eq!(value.get("value").and_then(DslValue::as_str),Some(if row["input"]["kind"]=="reference"{row["input"]["value"].as_str().unwrap()}else{""}));}else{assert_eq!(value.get("kind").and_then(DslValue::as_str),Some("typedValue"));let(name,items)=super::super::super::type_input::typed_constructor(value.get("value").unwrap()).unwrap();assert_eq!(name,"IFCPOSITIVELENGTHMEASURE");assert_eq!(items.len(),if row["input"]["kind"]=="typedValue"{row["input"]["value"]["items"].as_array().unwrap().len()}else{0});}}if !row["input"].is_null(){let child=prepared.control(1).unwrap();let StagedScalarKind::Text{value}=child.scalar.kind else{panic!("selected branch stays editable")};let raw=if row["input"]["kind"]=="reference"{row["input"]["value"].as_str().unwrap()}else{row["input"]["value"]["items"].as_array().unwrap().first().map(|value|value["value"]["bits"].as_str().unwrap()).unwrap_or("")};assert_eq!(value,raw);let StagedBodyBinding::Action(binding)=child.binding.unwrap()else{panic!("original scalar or reference binding")};let input=DslValue::String(raw.into());assert!(binding.plan(prepared.status(),Some(&input)).is_ok());}caller.cancel().cancel_now();super::type_guidance_request_tests::retire_owner(&mut caller,&mut output);super::type_guidance_request_tests::retire_owner(&mut caller,&mut guide);assert_eq!(Arc::strong_count(&snapshot),1);caller.finish();}
}
